// Get properties from trigger source
const webhookData = $('Webhook Trigger').item?.json?.body;
const scheduledData = $('Query New Listings').all()[0]?.json?.data;

// Determine source and get properties
let properties = [];
let contentType = 'new_listing';
let targetAudience = 'general';

if (webhookData && webhookData.property_id) {
  // From webhook - specific property
  const specificProperty = $('Query Specific Property').all()[0]?.json?.data?.[0];
  if (specificProperty) {
    properties = [specificProperty];
  }
  contentType = webhookData.content_type || 'custom';
  targetAudience = webhookData.target_audience || 'general';
} else if (scheduledData && scheduledData.length > 0) {
  // From schedule - new listings
  properties = scheduledData;
  contentType = 'new_listing';
  targetAudience = 'first_time_buyers';
}

// Determine target audience based on property price
function getTargetAudience(price) {
  if (price < 1500000) return 'first_time_buyers';
  if (price > 5000000) return 'luxury';
  if (price > 8000000) return 'investors';
  return 'families';
}

// Format features array or string
function formatFeatures(features) {
  if (Array.isArray(features)) return features.join(', ');
  if (typeof features === 'string') return features;
  return 'Modern kitchen, secure parking, garden';
}

// Build content for each property
const contentRequests = properties.map(prop => {
  const price = parseInt(prop.price) || 0;
  const audience = targetAudience !== 'general' ? targetAudience : getTargetAudience(price);

  return {
    json: {
      property_id: prop.id,
      address: prop.address || 'Unknown Address',
      suburb: prop.suburb || 'Unknown Suburb',
      city: prop.city || 'South Africa',
      property_type: prop.property_type || 'House',
      price: price,
      bedrooms: prop.bedrooms || 0,
      bathrooms: prop.bathrooms || 0,
      garages: prop.garages || 0,
      stand_size: prop.stand_size || 0,
      floor_size: prop.floor_size || 0,
      features: formatFeatures(prop.features),
      description: prop.description || '',
      unique_selling_point: prop.unique_selling_point || prop.highlight || 'Prime location with great potential',
      target_audience: audience,
      content_type: contentType,
      main_image_url: prop.main_image_url || ''
    }
  };
});

if (contentRequests.length === 0) {
  return [{
    json: {
      message: 'No properties found for social media content generation',
      source: webhookData ? 'webhook' : 'schedule'
    }
  }];
}

return contentRequests;

