// Parse Groq AI response
const groqResponse = $json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';
const propertyData = $('Batch Process').item.json;

// Extract JSON from response
let parsed;
try {
  // Find JSON in markdown code blocks or raw
  const jsonMatch = content.match(/```json\s*([\s\S]*?)```/) || content.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : content;
  parsed = JSON.parse(jsonStr);
} catch (e) {
  // Fallback if JSON parsing fails
  console.log('JSON parsing failed:', e.message);
  parsed = {
    facebook: {
      post: `🏠 New ${propertyData.property_type} available in ${propertyData.suburb}! ${propertyData.bedrooms} bed, ${propertyData.bathrooms} bath. Contact us for details.`,
      call_to_action: 'message us',
      character_count: 150
    },
    instagram: {
      caption: `Dream home alert in ${propertyData.suburb} ✨`,
      hashtags: ['#realestate', '#southafrica', '#property', '#home', '#forsale'],
      alt_text: `${propertyData.property_type} for sale in ${propertyData.suburb}`,
      character_count: 100
    },
    linkedin: {
      post: `New property listing: ${propertyData.property_type} in ${propertyData.suburb}. Contact us for viewing.`,
      hashtags: ['#RealEstate', '#Property'],
      character_count: 120
    },
    twitter: {
      post: `New ${propertyData.property_type} in ${propertyData.suburb}! 🏠`,
      hashtags: '#RealEstate #SAProperty',
      character_count: 80
    },
    image_suggestions: ['Front exterior photo', 'Main bedroom'],
    best_posting_time: 'Weekday 6-8 PM',
    content_theme: 'general'
  };
}

// Calculate character counts
const fb = parsed.facebook || {};
const ig = parsed.instagram || {};
const li = parsed.linkedin || {};
const tw = parsed.twitter || {};

return [{
  json: {
    property_id: propertyData.property_id,
    content_type: propertyData.content_type,
    target_audience: propertyData.target_audience,
    facebook_post: fb.post || '',
    facebook_cta: fb.call_to_action || 'message us',
    facebook_chars: (fb.post || '').length,
    instagram_caption: ig.caption || '',
    instagram_hashtags: ig.hashtags || [],
    instagram_alt_text: ig.alt_text || '',
    instagram_chars: (ig.caption || '').length + (ig.hashtags || []).join(' ').length,
    linkedin_post: li.post || '',
    linkedin_hashtags: li.hashtags || [],
    linkedin_chars: (li.post || '').length,
    twitter_post: tw.post || '',
    twitter_hashtags: tw.hashtags || '',
    twitter_chars: (tw.post || '').length + (tw.hashtags || '').length,
    image_suggestions: parsed.image_suggestions || [],
    best_posting_time: parsed.best_posting_time || 'Weekday 6-8 PM',
    content_theme: parsed.content_theme || 'general',
    generated_at: new Date().toISOString(),
    raw_response: content
  }
}];

